from sqlalchemy import select
from sqlalchemy.orm import Session

class CustomerRepository:
    def __init__(self, db: Session):
        self.db = db

    def get(self, customer_id: int) -> Customer | None:
        return self.db.get(Customer, customer_id)

    def get_by_email(self, email: str) -> Customer | None:
        return self.db.scalar(select(Customer).where(Customer.email == email))

    def add(self, customer: Customer) -> Customer:
        self.db.add(customer)
        self.db.flush()
        return customer

# Fake repository for unit tests: no database needed
class FakeCustomerRepository:
    def __init__(self):
        self.items = {}
    def get(self, customer_id):
        return self.items.get(customer_id)
    def get_by_email(self, email):
        return next((c for c in self.items.values() if c.email == email), None)
    def add(self, customer):
        customer.id = len(self.items) + 1
        self.items[customer.id] = customer
        return customer

from abc import ABC, abstractmethod

class PaymentGateway(ABC):
    @abstractmethod
    def charge(self, amount: float) -> str: ...

class RazorpayGateway(PaymentGateway):
    def charge(self, amount):
        return f"Razorpay charged {amount}"

class StripeGateway(PaymentGateway):
    def charge(self, amount):
        return f"Stripe charged {amount}"

GATEWAYS = {"razorpay": RazorpayGateway, "stripe": StripeGateway}

def get_gateway(name: str) -> PaymentGateway:
    try:
        return GATEWAYS[name]()
    except KeyError:
        raise ValueError(f"Unknown payment gateway: {name}")

