from abc import ABC, abstractmethod

class PointsRule(ABC):
    @abstractmethod
    def calculate(self, amount: float) -> int: ...

class SilverRule(PointsRule):
    def calculate(self, amount):
        return int(amount // 100) * 1          # 1 point per 100

class GoldRule(PointsRule):
    def calculate(self, amount):
        return int(amount // 100) * 2

class DoublePointsCampaign(PointsRule):        # wraps another rule
    def __init__(self, base: PointsRule):
        self.base = base
    def calculate(self, amount):
        return self.base.calculate(amount) * 2

RULES = {"silver": SilverRule(), "gold": GoldRule()}

def points_for(tier: str, amount: float, campaign_active: bool) -> int:
    rule = RULES[tier]
    if campaign_active:
        rule = DoublePointsCampaign(rule)
    return rule.calculate(amount)

print(points_for("gold", 1250, campaign_active=True))   # 48

from collections import defaultdict

class EventBus:
    def __init__(self):
        self.listeners = defaultdict(list)

    def subscribe(self, event: str, handler):
        self.listeners[event].append(handler)

    def publish(self, event: str, data: dict):
        for handler in self.listeners[event]:
            handler(data)

